 key=sys.argv[3];jobs=json.loads((run/'inputs/section_jobs_PRIVATE.json').read_text());job=next(z for z in jobs if z['section_code']==key);out=run/'sections'/key;out.mkdir(exist_ok=False);inf=pd.read_csv(run/'reference/signatures_PRIVATE.tsv',sep='\t',index_col=0);a=ad.read_h5ad(job['input_path'],backed='r');mask=a.obs[job['group_column']].astype(str).eq(job['group_value']).to_numpy() if job['group_column'] else np.ones(a.n_obs,bool)
