 pd.DataFrame(coords,index=b.obs_names,columns=['x','y']).to_csv(out/'coordinates_PRIVATE.tsv.gz',sep='\t');b.obs.to_csv(out/'spot_metadata_PRIVATE.tsv.gz',sep='\t');model.save(str(out/'fitted_model_PRIVATE'),overwrite=False);history=np.asarray(model.history['elbo_train']).ravel();np.save(out/'ELBO_history_PRIVATE.npy',history)
 receipt={'status':'FULL_30000_EPOCH_SPATIAL_FIT_COMPLETE_PENDING_AUDIT','UTC_start':start,'UTC_end':datetime.now(timezone.utc).isoformat(),'section_code':key,'dataset':job['dataset'],'n_spots':b.n_obs,'n_genes':b.n_vars,'n_reference_labels':len(names),'N_cells_per_location':5,'detection_alpha':20,'epochs_requested':30000,'epochs_recorded':len(history),'posterior_samples':1000,'mean_and_q05_exported':True,'ELBO_final':float(history[-1]),'coordinate_duplicates':0,'raw_counts_integer_nonnegative':True,'spot_independence_or_clinical_inference':False,'version':version,'reference_signature_sha256':hashlib.sha256((run/'reference/signatures_PRIVATE.tsv').read_bytes()).hexdigest()};(out/'complete.json').open('x').write(json.dumps(receipt,indent=2));print(json.dumps(receipt))
